# -*- coding: utf-8 -*-
# (speaker, spanish, korean); speaker None => stage direction, "#" => scene heading (neither is a turn)
L, A, D_, GA, R, V = "Lucas", "Amparo", "Daniel", "Gaby", "Ramón", "Vicente"
D = [
("#", "Escena 1 · 10:00 · Oficina de Daniel, almacén de Doral", "장면 1 · 오전 10시 · 도랄 창고, 대니얼의 사무실"),
(None, "Jueves 30 de julio. La oficina de Daniel está en un altillo de cristal sobre el almacén. Abajo, las carretillas mueven palés de porcelanato italiano. Sobre la mesa, tres maquetas de torres de vidrio y un plano de Brickell. El reporte firmado del laboratorio llegó ayer.", "7월 30일 목요일. 대니얼의 사무실은 창고 위 유리로 된 다락층에 있다. 아래에서는 지게차들이 이탈리아 포세린 팔레트를 옮기고 있다. 탁자 위에는 유리 타워 모형 세 개와 브리켈 지도가 놓여 있다. 시험소의 서명된 성적서는 어제 도착했다."),
(D_, "Siéntense, siéntense. Hoy no hay cafecito. Hoy hay business del bueno.", "앉아요, 앉아요. 오늘은 커피 없어요. 오늘은 진짜 비즈니스예요."),
(L, "Gaby nos avisó. Dijo que traías volumen.", "가비가 미리 알려 줬어요. 물량을 가져왔다고요."),
(D_, "(mira a su hija) Gaby avisa demasiado. Pero sí. Miren estas tres torres.", "(딸을 보며) 가비는 너무 많이 알려 줘. 하지만 맞아요. 이 세 타워를 봐요."),
(None, "Daniel señala las maquetas una por una.", "대니얼이 모형을 하나씩 가리킨다."),
(L, "¿Las tres son del mismo promotor?", "세 개 다 같은 개발사 거예요?"),
(D_, "Brisas de Brickell, cuarenta y dos pisos. Aurora, treinta y ocho. Palma Azul, treinta. El mismo developer, el mismo arquitecto y el mismo problema: necesitan piso para todos los apartamentos.", "브리사스 데 브리켈, 42층. 아우로라, 38층. 코럴 포인트, 30층. 같은 개발사, 같은 건축가, 같은 문제. 아파트 전체에 바닥재가 필요해요."),
(A, "¿Cuántos metros en total?", "전체 몇 제곱미터예요?"),
(GA, "Con Palma Azul entera ya no son cincuenta y cinco mil: son setenta y cinco mil metros cuadrados en dos años. Unos ochocientos mil pies. Brisas de Brickell empieza primero: treinta mil metros para el año que viene.", "팔마 아술까지 통째로 넣으면 5만 5천이 아니라 2년 동안 7만 5천 제곱미터예요. 피트로는 80만 평방피트쯤이에요. 브리사스 데 브리켈이 먼저 시작해요. 내년에 3만 제곱미터."),
(L, "(despacio) Setenta y cinco mil. Es más que todo México.", "(천천히) 7만 5천. 멕시코 전체보다 많네요."),
(A, "¿Y en contenedores, Gaby? ¿Cómo lo queréis recibir?", "컨테이너로는요, 가비? 어떻게 받고 싶어요?"),
(GA, "Escalonado. Unos cuatro contenedores al mes durante el primer año. Nuestro almacén no aguanta más, y el developer va piso por piso.", "나눠서요. 첫해엔 한 달에 컨테이너 네 개 정도. 우리 창고가 그 이상은 못 버티고, 개발사도 층별로 진행하거든요."),
(A, "Cuatro al mes son unos cinco mil metros. Eso el horno tres lo hace en una semana y media.", "한 달에 네 개면 5천 제곱미터쯤이에요. 그건 3호기가 일주일 반이면 만들어요."),
(D_, "Te lo dije, chico. Miami es fast y es big.", "내가 말했잖아요. 마이애미는 빠르고 크다고."),
(A, "¿Y qué mezcla de productos?", "제품 구성은요?"),
(GA, "Según el reporte del laboratorio: el «Blanco Biscayne» mate en el suelo de los apartamentos, el pulido en las paredes de los lobbies, el antideslizante en terrazas y baños. Y el roble claro en los dormitorios, si las muestras gustan.", "시험소 성적서대로요. 아파트 바닥엔 '블랑코 비스케인' 매트, 로비 벽엔 폴리싱, 테라스와 욕실엔 미끄럼 방지. 샘플이 마음에 들면 침실엔 밝은 참나무."),
(L, "Muy bien. ¿Y el precio que tenéis en mente?", "좋아요. 생각하는 가격은요?"),
(D_, "Antes del precio, una cosa. Los italianos ya me dieron número para Brisas de Brickell. No les voy a decir cuánto, pero les digo que el developer lo encontró caro.", "가격 전에 하나만. 이탈리아 업체가 벌써 브리사스 데 브리켈 견적을 줬어요. 얼마인지는 말 안 하겠지만, 개발사가 비싸다고 했다는 것만 말해 줄게요."),
(L, "¿Valdarno?", "발다르노요?"),
(D_, "No sé de qué me hablas. (sonríe) En Miami hay muchos italianos.", "무슨 말인지 모르겠는데. (웃으며) 마이애미엔 이탈리아 업체가 많아요."),
(A, "Entonces, ¿cuál es tu número?", "그럼 당신 숫자는 얼마예요?"),
(D_, "Aquí viene lo bueno. (escribe en una pizarra) Un dólar treinta y cinco el pie cuadrado. FOB Valencia. Todo el mix, el mismo precio.", "이제 본론이에요. (화이트보드에 쓰며) 평방피트당 1달러 35센트. FOB 발렌시아. 전 제품 같은 가격."),
(L, "(saca el móvil y calcula) Un treinta y cinco por diez coma setenta y seis... catorce cincuenta y ocho dólares el metro. Entre uno coma diez... trece veinticinco euros.", "(휴대폰을 꺼내 계산하며) 1.35 곱하기 10.76… 제곱미터당 14.58달러. 1.10으로 나누면… 13.25유로."),
(A, "Nuestra tarifa FOB es trece noventa. Uno cuarenta y dos el pie.", "저희 FOB 정가는 13.90유로예요. 평방피트당 1.42달러."),
(D_, "Siete centavos de diferencia por pie. Siete centavos, Amparo. Por setenta y cinco mil metros, ¿ustedes me van a discutir siete centavos?", "평방피트당 7센트 차이예요. 7센트요, 암파로. 7만 5천 제곱미터를 주는데 7센트를 따지겠다고요?"),
(A, "Siete centavos por ochocientos mil pies son cincuenta y seis mil dólares, Daniel.", "7센트 곱하기 80만 평방피트면 5만 6천 달러예요, 대니얼."),
(GA, "(sonríe sin querer) Ella hace las cuentas más rápido que tú, papi.", "(저도 모르게 웃으며) 아빠보다 계산이 빠르시네."),
(D_, "Gaby, tú estás de mi lado, ¿o no?", "가비, 너 내 편 맞지?"),
(GA, "Yo estoy del lado de los números. Y hay más condiciones, ¿verdad, papi? Díselas.", "난 숫자 편이야. 그리고 조건이 더 있잖아, 아빠? 말해."),
(D_, "(suspira) Dos condiciones. Una: el precio fijo durante los dos años. El developer me pide precio cerrado, así que yo se lo pido a ustedes.", "(한숨 쉬며) 조건 두 개. 첫째, 2년 동안 가격 고정. 개발사가 확정 가격을 요구하니까 나도 당신들한테 요구하는 거예요."),
(L, "¿Y la segunda?", "둘째는요?"),
(A, "Dos años es mucho tiempo, Daniel. El gas, el transporte marítimo... todo se mueve.", "2년은 긴 시간이에요, 대니얼. 가스, 해상 운송… 다 변해요."),
(D_, "Para eso están ustedes, para calcularlo. Yo vendo, ustedes fabrican. ¿Sigo?", "그걸 계산하라고 당신들이 있는 거죠. 나는 팔고, 당신들은 만들고. 계속할까요?"),
(L, "Sigue, por favor.", "계속하세요."),
(D_, "Pago a sesenta días desde la llegada del barco. Cuenta abierta. Nada de cartas de crédito, que los bancos aquí cobran un ojo de la cara.", "배 도착일부터 60일 뒤 결제. 외상 거래로요. 신용장은 안 돼요. 여기 은행들은 수수료를 엄청 떼거든요."),
(None, "Lucas y Amparo se miran. La palabra «cuenta abierta» cae sobre la mesa como una baldosa.", "루카스와 암파로가 서로를 쳐다본다. '외상 거래'라는 말이 타일 한 장처럼 탁자 위에 떨어진다."),
(L, "Daniel, es una propuesta muy seria y te la agradezco. Pero no podemos contestarte hoy.", "대니얼, 아주 진지한 제안이고 고마워요. 하지만 오늘 바로 답할 순 없어요."),
(D_, "¿No? ¿Y cuándo? En Miami, «mañana» ya es tarde.", "안 돼요? 그럼 언제요? 마이애미에선 '내일'이면 이미 늦어요."),
(A, "Esta tarde hablamos con Onda. Con nuestro director financiero y con mi padre.", "오늘 오후에 온다와 얘기해요. 재무이사와 우리 아버지랑요."),
(D_, "Okay. Esta tarde. Pero díganle a tu papá que esto no se ve dos veces en la vida.", "오케이. 오늘 오후. 하지만 아버님께 이런 기회는 평생 두 번 안 온다고 전해요."),

("#", "Escena 2 · 13:15 · Ventanita de un café cubano, calle Ocho", "장면 2 · 오후 1시 15분 · 칼레 오초, 쿠바 카페의 작은 창구"),
(None, "Comen de pie, frente a la ventanita de un café de la calle Ocho: dos cortaditos y dos pastelitos de guayaba. Por primera vez desde Monterrey, no están de acuerdo.", "칼레 오초의 카페 창구 앞에 서서 먹는다. 코르타디토 두 잔과 구아바 파이 두 개. 몬테레이 이후 처음으로 두 사람의 의견이 다르다."),
(L, "Amparo, piénsalo un momento. Setenta y cinco mil metros. El horno tres se queda sin trabajo en septiembre, cuando terminemos México.", "암파로, 잠깐만 생각해 봐요. 7만 5천 제곱미터예요. 멕시코 주문이 끝나면 9월부터 3호기가 일이 없어요."),
(A, "Ya lo sé.", "알아요."),
(L, "Si el horno se para otra vez, los treinta y dos vuelven al ERTE. Paco, el primero. Con este pedido, el horno tres trabaja dos años seguidos.", "가마가 또 서면 서른두 명이 다시 일시 휴직이에요. 파코가 제일 먼저고요. 이 주문이면 3호기가 2년 내내 돌아가요."),
(A, "Y a trece veinticinco, precio cerrado durante dos años. ¿Y si el gas vuelve a subir el año que viene? ¿Lo pagamos nosotros?", "그리고 13.25유로에 2년 가격 고정이죠. 내년에 가스비가 또 오르면요? 그건 우리가 내요?"),
(L, "No digo que aceptemos así. Digo que el volumen vale la pena. El precio se puede trabajar.", "그대로 받자는 게 아니에요. 물량은 그럴 가치가 있다는 거죠. 가격은 조정할 수 있고요."),
(A, "¿Trabajar cómo? Daniel ya ha dicho su número. Y es casi nuestro suelo.", "어떻게 조정해요? 대니얼은 벌써 자기 숫자를 말했어요. 그리고 그게 거의 우리 하한선이에요."),
(L, "Casi. No es el suelo. Hay cinco céntimos de aire.", "거의죠. 하한선은 아니에요. 5센트의 여유가 있어요."),
(A, "Cinco céntimos de aire... Con un contenedor que se retrase en Veracruz, se nos va el aire y el margen.", "5센트의 여유라… 컨테이너 하나만 베라크루스에서 늦어져도 그 여유도 마진도 다 날아가요."),
(L, "Por eso hay que negociar las condiciones, no solo el precio.", "그래서 가격만이 아니라 조건을 협상해야 하는 거예요."),
(A, "Lucas, si le das trece veinticinco a Daniel, ¿qué precio le vas a dar al de Texas la semana que viene? ¿Y a la gran cadena que viene detrás?", "루카스, 대니얼한테 13.25를 주면 다음 주 텍사스 사람한테는 얼마를 줄 거예요? 그 뒤에 올 대형 체인한테는요?"),
(L, "Cada cliente es distinto.", "고객마다 달라요."),
(A, "Los precios se saben. En este sector todo se sabe. Lo aprendí con BricoHogar: un descuento que das hoy es el precio que te piden mañana.", "가격은 다 알려져요. 이 업계는 다 알려져요. BricoHogar한테서 배웠어요. 오늘 준 할인은 내일 상대가 요구하는 가격이 돼요."),
(L, "Y yo lo aprendí con un horno parado: una fábrica vacía no tiene margen. No tiene nada.", "나는 멈춘 가마한테서 배웠어요. 빈 공장엔 마진도 없어요. 아무것도 없어요."),
(None, "Silencio. Un señor mayor, a su lado, pide un café en voz alta y les sonríe como si entendiera la discusión.", "침묵. 옆에 선 나이 든 남자가 큰 소리로 커피를 주문하고는, 두 사람의 다툼을 다 안다는 듯 미소 짓는다."),
(A, "Lo de la cuenta abierta me preocupa todavía más. Sesenta días sin garantía. ¿Te recuerda a algo?", "외상 거래가 더 걱정돼요. 담보 없이 60일. 생각나는 거 없어요?"),
(L, "Guadalajara.", "과달라하라."),
(A, "Guadalajara. Trescientos mil euros y un ERE. Mi padre no duerme si oye «cuenta abierta».", "과달라하라. 30만 유로와 정리해고. 아빠는 '외상 거래'라는 말만 들어도 잠을 못 자요."),
(L, "Daniel no es aquel distribuidor. Tiene tres showrooms y una empresa que existe desde mil novecientos setenta y tres.", "대니얼은 그 유통업자와 달라요. 쇼룸이 세 개고 1973년부터 있는 회사예요."),
(A, "Desde mil novecientos setenta y tres la llevaba su padre. Daniel firma desde hace mucho menos.", "1973년부터는 그분 아버지가 꾸려 왔죠. 대니얼이 서명하기 시작한 건 훨씬 나중이고요."),
(L, "Pero la casa es la misma. Ya me entiendes.", "그래도 같은 집안이잖아요. 무슨 말인지 알죠."),
(A, "Aquel también tenía showrooms. Lo que pido es simple: o bien un seguro de crédito, o bien una carta de crédito. Ni cuenta abierta sin nada, ni precio cerrado sin cláusula de gas.", "그 사람도 쇼룸이 있었어요. 내가 원하는 건 간단해요. 신용보험이든 신용장이든 둘 중 하나. 아무것도 없는 외상도, 가스 조항 없는 가격 고정도 안 돼요."),
(L, "Eso sí te lo compro. La garantía y la cláusula, sí. Pero el volumen no lo dejemos escapar.", "그건 받아들일게요. 보증이랑 조항은요. 하지만 물량은 놓치지 말아요."),
(A, "Y yo te compro el volumen, mientras no bajemos de trece cincuenta. Por debajo, que lo decida Ramón, no yo.", "그럼 나도 물량은 받아들일게요. 13.50 아래로만 안 내려가면요. 그 아래는 내가 아니라 라몬이 정하라고 해요."),
(L, "Trece cincuenta. Tú el margen, yo el volumen. Y que Ramón haga de árbitro.", "13.50. 당신은 마진, 나는 물량. 그리고 라몬이 심판을 보는 거죠."),
(A, "(apura el café) Como en Monterrey. Pero esta vez, sin mezcal.", "(커피를 비우며) 몬테레이 때처럼요. 이번엔 메스칼 없이."),

("#", "Escena 3 · 16:00 · Lobby del hotel, videollamada con Onda", "장면 3 · 오후 4시 · 호텔 로비, 온다와 화상 통화"),
(None, "En Onda son las diez de la noche. En la pantalla del portátil, Ramón aparece en su despacho con una hoja de cálculo abierta. Vicente, a su lado, con la chaqueta en el respaldo de la silla.", "온다는 밤 10시다. 노트북 화면에 라몬이 스프레드시트를 열어 둔 채 자기 사무실에 나타난다. 옆에는 비센테가 의자 등받이에 재킷을 걸쳐 놓고 앉아 있다."),
(V, "Buenas tardes, o buenas noches, ya no sé. Contadme. Amparo me ha mandado un mensaje que decía solo: «Volumen. Llámame.»", "안녕, 오후인지 밤인지 이제 모르겠다. 얘기해 봐. 암파로가 '물량. 전화해요.' 딱 그렇게 메시지를 보냈더라."),
(L, "Daniel propone setenta y cinco mil metros en dos años, para tres torres en Brickell. El primer año, treinta mil.", "대니얼이 브리켈 타워 세 개용으로 2년 동안 7만 5천 제곱미터를 제안했어요. 첫해는 3만."),
(R, "¿A qué precio?", "가격은?"),
(A, "Un dólar treinta y cinco el pie, FOB Valencia. Trece veinticinco euros el metro. Precio fijo dos años. Pago a sesenta días, cuenta abierta.", "평방피트당 1.35달러, FOB 발렌시아. 제곱미터당 13.25유로. 2년 가격 고정. 60일 외상 결제."),
(R, "(silba) Trece veinticinco FOB. Nuestro suelo es doce cincuenta en fábrica, que con el embalaje y el puerto son trece veinte FOB. Está cinco céntimos por encima del límite.", "(휘파람을 불며) FOB 13.25라. 우리 하한선이 공장 출고 12.50이고, 포장이랑 항구 비용 붙이면 FOB 13.20이야. 한계선보다 5센트 위네."),
(V, "Cinco céntimos. Como el banco de Monterrey: siempre al borde.", "5센트라. 몬테레이 때처럼 늘 아슬아슬하구나."),
(R, "Os hago las cuentas. Coste completo en FOB, diez con diez. A trece veinticinco ganamos tres con quince por metro. Por setenta y cinco mil metros, doscientos treinta y seis mil euros.", "계산해 줄게. FOB 기준 총원가 10.10. 13.25면 제곱미터당 3.15를 벌어. 7만 5천이면 23만 6천 유로."),
(L, "¿Y a trece noventa?", "13.90이면요?"),
(R, "Antes de que lo preguntes, Lucas: sí, es el precio más bajo que hemos dado nunca fuera de España.", "묻기 전에 말할게, 루카스. 맞아, 스페인 밖에서 우리가 준 가격 중 제일 낮아."),
(L, "Lo sé. Por eso quería tu número, no solo tu opinión.", "알아요. 그래서 의견만이 아니라 숫자가 필요했던 거예요."),
(R, "Tres con ochenta por metro. Doscientos ochenta y cinco mil. Unos cuarenta y nueve mil euros de diferencia.", "제곱미터당 3.80. 28만 5천. 차이는 4만 9천 유로쯤."),
(L, "Ramón, ahora haz la otra cuenta. ¿Qué pasa si el horno tres se para en septiembre?", "라몬, 이제 다른 계산도 해 봐요. 9월에 3호기가 서면 어떻게 돼요?"),
(R, "(teclea) Pues que los costes fijos se reparten entre dos hornos en vez de tres. El coste medio de toda la fábrica sube unos sesenta céntimos por metro. En un año, más que esos cuarenta y nueve mil.", "(자판을 두드리며) 고정비를 세 가마가 아니라 두 가마가 나눠 지게 되지. 공장 전체 평균 원가가 제곱미터당 60센트쯤 올라가. 1년이면 그 4만 9천보다 커."),
(L, "Entonces, cuanto antes llenemos el horno, mejor. El volumen merece la pena aunque el margen sea más bajo.", "그러니까 가마를 빨리 채울수록 좋아요. 마진이 낮아도 물량은 그럴 가치가 있어요."),
(R, "Despacio, Lucas. Eso es verdad si se cumplen tres cosas: que Daniel pague, que el gas no se dispare y que no vendamos lo mismo más barato a otros.", "천천히, 루카스. 그건 세 가지가 지켜질 때 얘기야. 대니얼이 돈을 내고, 가스비가 폭등하지 않고, 같은 걸 다른 데 더 싸게 팔지 않을 때."),
(A, "Es lo que yo digo. Ramón, el precio fijo dos años sin cláusula de gas me da miedo.", "내 말이 그거예요. 라몬, 가스 조항 없이 2년 가격 고정은 무서워요."),
(L, "¿Y si le contraofertamos trece cincuenta? Es lo que hemos hablado Amparo y yo a mediodía.", "13.50으로 역제안하면요? 점심때 암파로랑 얘기한 게 그거예요."),
(R, "(teclea) Trece cincuenta son... un dólar treinta y ocho el pie. Tres centavos más por pie que su número. Ganaríamos tres cuarenta por metro: doscientos cincuenta y cinco mil en total.", "(자판을 두드리며) 13.50이면… 평방피트당 1.38달러. 대니얼 숫자보다 평방피트당 3센트 높아. 제곱미터당 3.40을 버니까 전체 25만 5천."),
(V, "Tres centavos. Lo puede aceptar sin perder la cara delante de su promotor.", "3센트라. 그 정도면 개발사 앞에서 체면 안 깎이고 받아들일 수 있겠다."),
(R, "A mí también. Yo que vosotros pediría revisión anual del precio, ligada al precio del gas. Con un tope, para que el cliente no se asuste.", "나도 그래. 내가 너희라면 가스 가격에 연동한 연간 가격 재조정을 요구하겠어. 고객이 겁먹지 않게 상한선을 두고."),
(L, "¿Y la cuenta abierta?", "외상 거래는요?"),
(R, "Ni hablar. Sesenta días, sí, pero con seguro de crédito. Si la aseguradora le da cobertura a Daniel, firmamos. Si no se la da, por algo será.", "말도 안 돼. 60일은 괜찮아. 하지만 신용보험을 붙여서. 보험사가 대니얼한테 한도를 내주면 서명하고, 안 내주면 다 이유가 있는 거지."),
(V, "Escuchadme los dos. (se acerca a la cámara) En dos mil nueve, el error no fue el precio. Fue la prisa. Nos dijeron «ahora o nunca» y firmamos.", "둘 다 들어 봐라. (카메라 쪽으로 다가앉으며) 2009년에 실수는 가격이 아니었어. 서두른 거였지. '지금 아니면 끝'이라는 말에 서명했거든."),
(A, "Papá, Daniel ha dicho exactamente eso: «esto no se ve dos veces en la vida».", "아빠, 대니얼이 딱 그 말을 했어요. '이런 기회는 평생 두 번 안 온다'고요."),
(V, "Pues por eso mismo. Convendría que esperarais. ¿No vais a Texas el lunes?", "그러니까 더더욱. 기다리는 게 좋겠다. 월요일에 텍사스 가잖니?"),
(L, "Sí. Una constructora de viviendas en San Antonio.", "네. 샌안토니오의 주택 건설사요."),
(R, "Y después, la gran cadena, ¿no? La que te presenta Daniel.", "그다음엔 그 대형 체인이지? 대니얼이 소개해 준다는 데."),
(A, "Si se confirma, sí. Por eso no podemos poner un precio en Miami sin saber qué nos van a pedir los demás.", "확정되면요. 그래서 다른 데서 뭘 요구할지 모르면서 마이애미에 가격을 박아 둘 순 없어요."),
(V, "Entonces id a Texas, ved qué precios se mueven allí y volved a hablar con Daniel con toda la información. Una semana no mata a nadie.", "그럼 텍사스에 가서 거기 가격이 어떻게 움직이는지 보고, 정보를 다 갖고 대니얼과 다시 얘기해라. 일주일로 죽는 사람은 없다."),
(L, "¿Y si Daniel se va con los italianos mientras tanto?", "그사이에 대니얼이 이탈리아 업체로 가 버리면요?"),
(V, "Si se va por una semana, es que no era para nosotros. Y si te espera, sabrás que te respeta. Lucas, a veces esperar también es negociar.", "일주일 때문에 가 버리면 우리 짝이 아니었던 거지. 기다려 주면 너를 존중한다는 걸 알게 될 거고. 루카스, 때로는 기다리는 것도 협상이다."),
(R, "Y mientras tanto, yo pido la cobertura del seguro para Ruiz-Walker. Así, cuando volváis, ya sabremos cuánto crédito le podemos dar.", "그동안 나는 루이스-워커 앞으로 보험 한도를 신청해 둘게. 그러면 너희가 돌아올 때쯤 얼마까지 외상을 줄 수 있는지 알게 되겠지."),
(A, "Gracias, Ramón. Papá, gracias.", "고마워요, 라몬. 아빠, 고마워요."),
(V, "Y una cosa más. No os peleéis por esto. Uno que mire el horno y otra que mire el margen: así se ha llevado esta casa durante sesenta años.", "그리고 하나 더. 이 일로 싸우지 마라. 한 사람은 가마를 보고, 한 사람은 마진을 보고. 이 회사는 60년 동안 그렇게 꾸려 왔다."),
(L, "Lo sabemos. Ya lo hemos hablado comiendo pastelitos de guayaba.", "알아요. 구아바 파이 먹으면서 벌써 얘기했어요."),
(V, "¿Pastelitos de qué? Bueno, da igual. Buenas noches. O buenas tardes.", "무슨 파이? 뭐, 됐다. 잘 자라. 아니면 좋은 오후 보내든가."),

("#", "Escena 4 · 18:00 · Oficina de Daniel", "장면 4 · 오후 6시 · 대니얼의 사무실"),
(None, "Daniel los recibe de pie, con los brazos cruzados. Gaby está sentada en el sofá con la tableta.", "대니얼이 팔짱을 낀 채 서서 두 사람을 맞는다. 가비는 태블릿을 들고 소파에 앉아 있다."),
(D_, "¿Y bien? ¿Qué dijo el papá?", "그래서? 아버님이 뭐래요?"),
(L, "Daniel, te voy a hablar claro, como te gusta a ti. Tu propuesta nos interesa mucho. Pero no te vamos a dar una respuesta hasta dentro de diez días.", "대니얼, 당신이 좋아하는 방식대로 솔직하게 말할게요. 제안은 아주 관심 있어요. 하지만 열흘 뒤에야 답을 줄 수 있어요."),
(D_, "¿Diez días? (levanta los brazos) ¡Diez días! En diez días se construye medio building en Miami.", "열흘이요? (두 팔을 들며) 열흘! 마이애미에선 열흘이면 건물 반이 올라가요."),
(GA, "Papi, el developer no firma nada hasta septiembre. Lo dijo él mismo el lunes.", "아빠, 개발사도 9월 전엔 아무것도 서명 안 해. 월요일에 본인이 그랬잖아."),
(D_, "(a Gaby, en voz baja) ¿Tú de qué lado estás hoy?", "(가비에게 작은 목소리로) 너 오늘 누구 편이야?"),
(GA, "Del lado de la empresa, papi. Como siempre.", "회사 편이지, 아빠. 늘 그렇듯이."),
(A, "Y en diez días tú también puedes pedir otras ofertas. Nos parece justo.", "그리고 열흘이면 당신도 다른 견적을 받아 볼 수 있죠. 저희는 그게 공정하다고 봐요."),
(D_, "¿Y qué van a hacer en diez días que no puedan hacer hoy?", "열흘 동안 오늘은 못 하는 뭘 하려고요?"),
(L, "Tres cosas. Ver otro mercado, preparar una cláusula de precio que nos proteja a los dos, y pedir la cobertura del seguro de crédito.", "세 가지요. 다른 시장을 보고, 양쪽 다 보호하는 가격 조항을 준비하고, 신용보험 한도를 신청하는 거요."),
(D_, "¿Seguro de crédito? ¿Ustedes no se fían de mí?", "신용보험? 날 못 믿는다는 거예요?"),
(L, "Nos fiamos tanto que queremos que el banco y la aseguradora también se fíen. Con el seguro, te podemos dar sesenta días sin carta de crédito.", "믿으니까 은행이랑 보험사도 믿게 하고 싶은 거예요. 보험이 있으면 신용장 없이 60일을 드릴 수 있어요."),
(GA, "Papi, es normal. Nosotros a los contractors nuevos también les pedimos garantía. Y tú dices que es «business, no personal».", "아빠, 그거 당연한 거야. 우리도 새 시공업자한테는 보증을 요구하잖아. 아빠도 늘 '비즈니스지 개인적인 거 아니다'라고 하고."),
(D_, "(mira a su hija, luego a Lucas, y se ríe) Esta muchacha me va a quitar el negocio un día de estos.", "(딸을 보고, 루카스를 보더니 웃으며) 이 아가씨가 언젠가 내 사업을 빼앗아 갈 거예요."),
(A, "Daniel, a cambio de esos diez días, te prometemos una cosa: no le daremos este precio a nadie en Florida mientras hablamos contigo.", "대니얼, 그 열흘을 주는 대신 약속할게요. 당신과 얘기하는 동안 플로리다에서 누구한테도 이 가격을 주지 않을게요."),
(L, "Y otra: cuando volvamos, traeremos una propuesta por escrito. Con precio, con cláusula y con fechas. Nada de «ya veremos».", "그리고 하나 더. 돌아오면 서면 제안서를 가져올게요. 가격, 조항, 날짜까지 다 넣어서. '두고 보자' 같은 건 없어요."),
(D_, "Mmm. Eso ya me gusta más. ¿Y adónde van, si se puede saber? ¿A ver a la competencia?", "음. 그건 좀 낫네요. 어디 가는데요, 물어봐도 되면? 경쟁자 만나러?"),
(L, "A Texas. El lunes, a San Antonio.", "텍사스요. 월요일에 샌안토니오."),
(D_, "¿Texas? (suelta una carcajada) ¡Texas! Eso es otro país, chico. Allá el español es otro, la comida es otra y los negocios se cierran en una troca.", "텍사스? (크게 웃으며) 텍사스! 거긴 다른 나라예요. 거기선 스페인어도 다르고, 음식도 다르고, 거래는 픽업트럭 안에서 끝나요."),
(GA, "Pídanle a la señora que los lleve a comer barbacoa. Allí la barbacoa es una religión.", "그분한테 바비큐 먹으러 데려가 달라고 하세요. 거기선 바비큐가 종교예요."),
(D_, "Vayan, vayan. Pero en diez días los quiero aquí con una respuesta. Y si es que no, me lo dicen a la cara, como hombres... (mira a Amparo) y como mujeres.", "가요, 가. 하지만 열흘 뒤엔 답을 갖고 여기 와요. 거절이면 남자답게 얼굴 보고 말해요… (암파로를 보며) 여자답게도."),
(A, "(sonríe) A la cara. Como en Onda.", "(미소 지으며) 얼굴 보고요. 온다에서처럼."),
(None, "Daniel vuelve a mirar las maquetas. Gaby acompaña a Lucas y Amparo hasta la escalera.", "대니얼이 다시 모형을 내려다본다. 가비가 루카스와 암파로를 계단까지 배웅한다."),
(GA, "(en voz baja) Gracias por no decir que sí hoy. Mi papá también necesita estos diez días, aunque no lo diga.", "(작은 목소리로) 오늘 바로 좋다고 하지 않아 줘서 고마워요. 아빠도 이 열흘이 필요해요. 말은 안 하지만."),
(L, "Lo sabemos, Gaby. Nos vemos en diez días. Con todo por escrito.", "알아요, 가비. 열흘 뒤에 봐요. 전부 문서로 가져올게요."),
]

PRE = [
("text", "장면 미리보기", "대화문을 읽기 전에 줄거리를 확인하고, 아래 질문의 답을 찾으며 읽어 보세요.", [
 "목요일 아침, 대니얼이 브리켈의 유리 타워 세 동을 탁자 위에 올린다. 2년 동안 7만 5천 제곱미터, 3호기를 계속 돌릴 수 있는 물량이다. 하지만 가격은 라몬이 정한 하한선에서 겨우 5센트 위이고, 2년 가격 고정에 담보 없는 외상 거래까지 붙어 있다. 점심때 칼레 오초의 카페 창구 앞에서 루카스와 암파로의 의견이 처음으로 갈리고, 밤 10시의 온다와 연결한 화상 회의에서 라몬은 계산기를, 비센테는 2009년의 기억을 꺼낸다.",
 "듣기 질문 ① 대니얼이 제시한 물량, 가격(평방피트당·제곱미터당), 두 가지 조건은 무엇인가?",
 "듣기 질문 ② 루카스가 물량을, 암파로가 마진을 지지하는 이유는 각각 무엇인가?",
 "듣기 질문 ③ 라몬과 비센테가 내놓은 해법과 대니얼에게 한 약속은 무엇인가?",
]),
]

